INSERT INTO dm_story_cards (category, subcategory, title, content, skill_check, difficulty) VALUES
('yol', 'Orman Yolu', 'Devrilmiş Ağaç', 'Yolun ortasında devasa bir meşe ağacı devrilmiş. Altından geçmek tehlikeli görünüyor, etrafından dolaşmak ise karanlık ormana girmeyi gerektiriyor.', 'd20 → 5+güç', 'kolay'),
('yol', 'Orman Yolu', 'Kurt Sürüsü', 'Uzaktan uluma sesleri yaklaşıyor. Ağaçların arasında parlayan gözler görünüyor. Kurt sürüsü grubun etrafını sarıyor.', 'd20 → 8+zeka', 'orta'),
('yol', 'Orman Yolu', 'Kayıp Gezgin', 'Yol kenarında yaralı bir gezgin yatıyor. Yardım istiyor ama üzerindeki kıyafetler şüpheli — belki bir haydut tuzağı?', 'd20 → 6+karizma', 'kolay'),
('yol', 'Orman Yolu', 'Zehirli Mantar Tarlası', 'Yol boyunca rengârenk mantarlar yayılmış. Spor saçıyorlar ve havayı bulandırıyorlar.', 'd20 → 7+zeka', 'orta'),
('yol', 'Orman Yolu', 'Ağaç Ruhu', 'Antik bir ağacın gövdesinde yüzler beliriyor. Ağaç ruhu geçiş izni istiyor — bir bilmece soruyor.', 'd20 → 10+zeka', 'zor'),
('yol', 'Orman Yolu', 'Yıkık Köprü', 'Dere üzerindeki ahşap köprü çürümüş. Karşıya geçmek için başka yol bulunmalı.', 'd20 → 6+güç', 'kolay'),
('yol', 'Orman Yolu', 'Sis Perdesi', 'Aniden yoğun bir sis çöküyor. Yön bulmak neredeyse imkânsız.', 'd20 → 8+zeka', 'orta'),
('yol', 'Orman Yolu', 'Örümcek Ağları', 'Dev örümcek ağları yolu kapatmış. Ağların sahibi muhtemelen yakında.', 'd20 → 7+atak', 'orta'),
('yol', 'Dağ Yolu', 'Heyelan', 'Dağ yamacından kayalar yuvarlanıyor. Hızlı hareket etmezseniz altında kalabilirsiniz.', 'd20 → 8+güç', 'orta'),
('yol', 'Dağ Yolu', 'Kartal Yuvası', 'Dev kartallar yuva yapıyor ve saldırgan. Yavruları korumak için dalma atağa geçiyorlar.', 'd20 → 9+savunma', 'orta'),
('yol', 'Dağ Yolu', 'Dondurucu Fırtına', 'Ani bir kar fırtınası bastırıyor. Sığınak bulmak şart yoksa donma riski var.', 'd20 → 7+zeka', 'orta'),
('yol', 'Dağ Yolu', 'Dar Geçit', 'Uçurumun kenarında daracık bir patika. Tek sıra halinde geçilmeli.', 'd20 → 6+güç', 'kolay'),
('yol', 'Dağ Yolu', 'Maden Çökmesi', 'Eski bir maden girişi çökmüş ve yolu kapatmış. Kazıp geçmek ya da tırmanmak lazım.', 'd20 → 8+güç', 'orta'),
('yol', 'Dağ Yolu', 'Dağ Devleri', 'Uzaktan dev adım sesleri duyuluyor. Devler yolda yürüyor — saklanmak gerek.', 'd20 → 10+zeka', 'zor'),
('yol', 'Dağ Yolu', 'Lavlı Yarık', 'Dağın yamacında erimiş kayadan akan lavlar yolu kesiyor.', 'd20 → 9+güç', 'zor'),
('yol', 'Dağ Yolu', 'Antik Sunak', 'Yol kenarında eski bir sunak var. Üzerinde garip semboller kazılı ve hafif bir ışık yayıyor.', 'd20 → 7+zeka', 'orta'),
('yol', 'Çöl Yolu', 'Kum Fırtınası', 'Ufuktan yaklaşan devasa kum bulutu her şeyi yutacak gibi görünüyor.', 'd20 → 8+savunma', 'orta'),
('yol', 'Çöl Yolu', 'Serap', 'Uzakta bir vaha görünüyor ama gerçek mi yoksa hayal mi? Susuzluk beyni yanıltıyor.', 'd20 → 7+zeka', 'orta'),
('yol', 'Çöl Yolu', 'Çöl Akrepleri', 'Kumun altından dev akrepler çıkıyor. Zehirleri öldürücü.', 'd20 → 9+atak', 'zor'),
('yol', 'Çöl Yolu', 'Gömülü Harabe', 'Kumların arasından antik bir yapının tepesi görünüyor. İçinde hazine olabilir — ya da tuzak.', 'd20 → 6+zeka', 'kolay'),
('yol', 'Çöl Yolu', 'Göçebe Kervanı', 'Bir göçebe kervanı yolda duraklamış. Ticaret teklif ediyorlar ama fiyatları absürt.', 'd20 → 8+karizma', 'orta'),
('yol', 'Çöl Yolu', 'Kum Kurdu', 'Yerin altından titreşimler geliyor. Devasa bir kum kurdu yaklaşıyor.', 'd20 → 11+güç', 'zor'),
('yol', 'Çöl Yolu', 'Susuz Vaha', 'Nihayet bir vaha! Ama su kaynağı kurumuş. Etrafta kemikler var.', 'd20 → 7+zeka', 'orta'),
('yol', 'Ova Yolu', 'Haydut Pususu', 'Yol kenarındaki çalılardan oklar yağıyor. Haydutlar parasını ister!', 'd20 → 7+atak', 'orta'),
('yol', 'Ova Yolu', 'Çiftçi Kavgası', 'İki çiftçi arazi konusunda kavga ediyor. Grubun hakemliğini istiyorlar.', 'd20 → 6+karizma', 'kolay'),
('yol', 'Ova Yolu', 'Kaçak Mahkûm', 'Zincirlerini kırmış bir mahkûm yardım istiyor. Masum mu yoksa tehlikeli mi?', 'd20 → 7+karizma', 'orta'),
('yol', 'Ova Yolu', 'Batık Araba', 'Bir tüccar arabası çamura saplanmış. Yardım edersen ödül vaat ediyor.', 'd20 → 5+güç', 'kolay'),
('yol', 'Ova Yolu', 'Yaban Atları', 'Bir yaban atı sürüsü ovada koşuyor. Birini yakalamak işe yarar mı?', 'd20 → 9+güç', 'orta'),
('yol', 'Ova Yolu', 'Tuhaf Satıcı', 'Yol kenarında tek başına oturan bir satıcı. Sadece "anılar" satıyor diyor...', 'd20 → 8+zeka', 'orta'),
('yol', 'Ova Yolu', 'Yanık Köy', 'Yol kenarında yakılmış bir köy kalıntısı. İçinden hâlâ duman çıkıyor.', 'd20 → 6+zeka', 'kolay'),
('yol', 'Ova Yolu', 'Gizemli Taş', 'Yolun ortasında parlayan rünlerle kaplı bir taş duruyor. Dokunmak cesaret ister.', 'd20 → 8+zeka', 'orta'),
('yol', 'Bataklık', 'Bataklık Gazı', 'Havada yeşilimsi bir gaz yayılıyor. Nefes almak zorlaşıyor.', 'd20 → 7+savunma', 'orta'),
('yol', 'Bataklık', 'Çürük Köprü', 'Bataklığı geçiren tahta köprü çürümüş. Her adımda kırılabilir.', 'd20 → 6+güç', 'kolay'),
('yol', 'Bataklık', 'Bataklık Cadısı', 'Sisler arasından bir kadın sesi şarkı söylüyor. Peşinden gitmek tehlikeli ama cazip.', 'd20 → 9+zeka', 'zor'),
('yol', 'Bataklık', 'Sülükler', 'Suya bastığınızda bacaklarınıza dev sülükler yapışıyor.', 'd20 → 5+güç', 'kolay'),
('yol', 'Bataklık', 'Işıklar', 'Bataklıkta dans eden ışıklar görünüyor. Onları takip edenler kaybolur derler.', 'd20 → 8+zeka', 'orta'),
('yol', 'Sahil Yolu', 'Deniz Korsanları', 'Sahilde demirli bir korsan gemisi var. Mürettebat karaya çıkmış ve kavgacı görünüyor.', 'd20 → 8+atak', 'orta'),
('yol', 'Sahil Yolu', 'Karaya Vuran Sandık', 'Dalgalar kıyıya kilitli bir sandık vurmuş. İçinde ne olduğu belirsiz.', 'd20 → 5+güç', 'kolay'),
('yol', 'Sahil Yolu', 'Denizkızı Şarkısı', 'Kayalıkların arkasından büyüleyici bir şarkı geliyor. Yaklaşmak tehlikeli olabilir.', 'd20 → 9+karizma', 'zor'),
('yol', 'Sahil Yolu', 'Gelgit Tuzağı', 'Gelgit yükseliyor ve geçtiğiniz geçit kapanmak üzere. Koşmanız lazım!', 'd20 → 7+güç', 'orta'),
('yol', 'Gece Yolu', 'Hayalet Kervan', 'Gece vakti ışıklı bir kervan geçiyor ama insanlar soluk ve şeffaf…', 'd20 → 8+karizma', 'orta'),
('yol', 'Gece Yolu', 'Kamp Ateşi', 'Yol kenarında terk edilmiş bir kamp ateşi hâlâ yanıyor. Etrafta kimse yok.', 'd20 → 6+zeka', 'kolay'),
('yol', 'Gece Yolu', 'Ay Işığı Ritüeli', 'Ay ışığı altında dans eden figürler. Yaklaşırsanız sizi de davet ederler.', 'd20 → 9+karizma', 'zor'),
('yol', 'Gece Yolu', 'Vampir Yarasalar', 'Karanlıktan vampir yarasalar sürüsü saldırıyor.', 'd20 → 7+atak', 'orta'),
('yol', 'Gece Yolu', 'Mezarlık Geçişi', 'Yol eski bir mezarlıktan geçiyor ve yerden ışıklar sızıyor.', 'd20 → 8+savunma', 'orta'),
('yol', 'Köprü', 'Trol Köprüsü', 'Köprünün altında yaşayan bir trol geçiş ücreti istiyor: altın veya bilmece.', 'd20 → 8+karizma', 'orta'),
('yol', 'Köprü', 'Çöken Taş Köprü', 'Köprünün taşları parçalanıyor. Her adımda daha çok çatlıyor.', 'd20 → 7+güç', 'orta'),
('yol', 'Nehir', 'Nehir Geçişi', 'Akıntı çok güçlü. Karşıya geçmek için sal yapmak ya da yüzmek lazım.', 'd20 → 7+güç', 'orta'),
('yol', 'Nehir', 'Su Perileri', 'Nehirde parlayan figürler beliriyor. Yardım mı edecekler, yoksa derinlere mi çekecekler?', 'd20 → 8+karizma', 'orta'),
('yol', 'Nehir', 'Timsah Sürüsü', 'Sığ suda dev timsahlar güneşleniyor. Farkında olmadan aralarına girdiniz.', 'd20 → 8+atak', 'orta'),
('yol', 'Genel', 'Yol Çatalı', 'İki yol ayrımı: Biri kısa ama tehlikeli görünüyor, diğeri uzun ama güvenli.', 'd20 → 6+zeka', 'kolay'),
('yol', 'Genel', 'Kaybolan Yol', 'İz tamamen kayboluyor. Etraf mı değişti yoksa siz mi kayıp oldunuz?', 'd20 → 8+zeka', 'orta'),
('yol', 'Genel', 'Terk Edilmiş Kamp', 'Yeni terk edilmiş bir kamp. Eşyalar dağınık, kan izleri var.', 'd20 → 6+zeka', 'kolay'),
('yol', 'Genel', 'Dilenci', 'Yol kenarında kör bir dilenci oturuyor. Aslında güçlü bir büyücü olabilir.', 'd20 → 7+karizma', 'orta'),
('yol', 'Genel', 'Hava Değişimi', 'Gökyüzü kararıyor. Yıldırımlar çakıyor. Fırtına yaklaşıyor.', 'd20 → 6+savunma', 'kolay'),
('yol', 'Genel', 'Eski Tapınak', 'Yol kenarında yıkık bir tapınak. İçinden garip sesler geliyor.', 'd20 → 7+zeka', 'orta'),
('yol', 'Genel', 'Harita Parçası', 'Yolda bir harita parçası buluyorsunuz. Hazineye mi götürüyor?', 'd20 → 5+zeka', 'kolay'),
('yol', 'Genel', 'Yolcu Kervancı', 'Bir kervancı sizi uyarıyor: İleride bir sorun var diyor ama detay vermiyor.', 'd20 → 7+karizma', 'orta'),
('yol', 'Genel', 'Büyülü Pınar', 'Yol kenarında mavi ışıldayan bir pınar. İçenin başına ne gelir kimse bilmez.', 'd20 → 8+zeka', 'orta'),
('yol', 'Genel', 'Düşman İzi', 'Yerde büyük ve taze ayak izleri. Bir şey sizi takip ediyor olabilir.', 'd20 → 7+zeka', 'orta'),
('yol', 'Genel', 'Tuhaf Heykel', 'Yol ortasında taştan bir heykel. Gözleri sizi takip ediyor gibi.', 'd20 → 7+zeka', 'orta'),
('yol', 'Genel', 'Kırık Kılıç', 'Yolda parçalanmış bir kılıç ve zırh parçaları. Burada bir savaş olmuş.', 'd20 → 5+zeka', 'kolay'),
('yol', 'Genel', 'Tilki Ailesi', 'Yavru tilkiler yolda oynuyor. Anne tilki kızgın görünüyor.', 'd20 → 5+karizma', 'kolay'),
('yol', 'Genel', 'Kayıp Çocuk', 'Ağlayan bir çocuk ormanda kaybolmuş diyor. Ama etrafta köy yok…', 'd20 → 7+karizma', 'orta'),
('yol', 'Genel', 'Rün Taşı', 'Büyülü rünlerle kaplı bir yol taşı. Üzerine basınca ne olur?', 'd20 → 8+zeka', 'orta'),
('yol', 'Genel', 'Hızlı Nehir', 'Yol bir nehirle kesilmiş. Tek geçiş yolu ıslak kayalar üzerinden atlamak.', 'd20 → 6+güç', 'kolay'),
('yol', 'Genel', 'Mezar Taşları', 'Yol kenarında isimsiz mezar taşları dizili. En sonuncusu henüz kazılmış.', 'd20 → 7+zeka', 'orta'),
('yol', 'Genel', 'Doğa Büyüsü', 'Çiçekler alışılmadık şekilde açıyor. Bölgede güçlü bir doğa büyüsü var.', 'd20 → 6+zeka', 'kolay'),
('yol', 'Genel', 'Ücretli Geçit', 'Silahlı muhafızlar yolda barikat kurmuş. Geçiş ücreti talep ediyorlar.', 'd20 → 7+karizma', 'orta'),
('yol', 'Genel', 'Çığlık', 'Yolun ilerisinden çığlıklar duyuluyor. Koşup baksanız mı?', 'd20 → 6+güç', 'kolay'),
('yol', 'Genel', 'Yolcu Hırsızı', 'Uyurken biri çantanızı karıştırıyor! Hırsızı yakalamak lazım.', 'd20 → 7+güç', 'orta'),
('yol', 'Genel', 'Sisli Geçit', 'Aniden her yer sise kaplandı. Pusula bile çalışmıyor.', 'd20 → 8+zeka', 'orta'),
('yol', 'Genel', 'Ateş Böcekleri', 'Gece olunca binlerce ateş böceği ortaya çıkıyor. Güzel ama bir yere doğru sürüklüyorlar.', 'd20 → 6+zeka', 'kolay'),
('yol', 'Genel', 'Yıkık Han', 'Yol kenarında terk edilmiş bir han. İçeride belki hâlâ işe yarar malzeme vardır.', 'd20 → 5+zeka', 'kolay'),
('yol', 'Genel', 'Tuzak Çukuru', 'Yapraklarla örtülü bir çukur! Son anda fark etmezsen düşersin.', 'd20 → 7+zeka', 'orta'),
('yol', 'Genel', 'Büyücü Kuşu', 'Konuşan bir karga dala konuyor ve garip bir mesaj iletiyor.', 'd20 → 6+zeka', 'kolay'),
('yol', 'Genel', 'Ağlayan Taş', 'Yol kenarındaki bir kaya gerçekten ağlıyor. Taşa mı lanet okunmuş?', 'd20 → 7+zeka', 'orta');
INSERT INTO dm_story_cards (category, subcategory, title, content, skill_check, difficulty) VALUES
('zindan', 'Giriş', 'Kilitli Kapı', 'Zindanın ana kapısı dev bir asma kilitle kilitli. Kilit paslı ama sağlam.', 'd20 → 6+zeka', 'kolay'),
('zindan', 'Giriş', 'Çökmüş Tavan', 'Girişin bir kısmı çökmüş. Molozların arasından sıyrılmak lazım.', 'd20 → 7+güç', 'orta'),
('zindan', 'Giriş', 'İskelet Muhafız', 'Girişi koruyan bir iskelet savaşçı canlanıyor.', 'd20 → 7+atak', 'orta'),
('zindan', 'Giriş', 'Rünlü Eşik', 'Eşikte parlayan rünler. Üzerine basanı elektrik çarpıyor.', 'd20 → 8+zeka', 'orta'),
('zindan', 'Giriş', 'Karanlık Koridor', 'İçerisi zifiri karanlık. Meşalesiz hareket etmek imkânsız.', 'd20 → 5+zeka', 'kolay'),
('zindan', 'Koridor', 'Dikenli Duvar', 'Duvarlardan dikenler çıkıyor. Koridor daralıyor.', 'd20 → 8+güç', 'orta'),
('zindan', 'Koridor', 'Dönen Zemin', 'Zemin aniden dönmeye başlıyor. Dengenizi kaybetmemelisiniz.', 'd20 → 7+güç', 'orta'),
('zindan', 'Koridor', 'Gaz Tuzağı', 'Duvardan yeşil gaz sızıyor. Zehirli olabilir.', 'd20 → 7+savunma', 'orta'),
('zindan', 'Koridor', 'Sahte Zemin', 'Zemin tahtaları çürük. Altında derin bir boşluk var.', 'd20 → 7+zeka', 'orta'),
('zindan', 'Koridor', 'Ok Tuzağı', 'Bir basınç plakasına bastınız! Duvarlardan oklar fırlıyor.', 'd20 → 8+savunma', 'orta'),
('zindan', 'Koridor', 'Hareket Eden Duvarlar', 'Duvarlar yavaşça birbirine yaklaşıyor. Ezilmeden çıkmalısınız!', 'd20 → 9+güç', 'zor'),
('zindan', 'Koridor', 'Ayna Koridoru', 'Her duvar ayna. Gerçek yolu bulmak için dikkatli olmak lazım.', 'd20 → 8+zeka', 'orta'),
('zindan', 'Koridor', 'Fısıltılar', 'Duvarlardan fısıltılar geliyor. Deli mi edecekler yoksa ipucu mu?', 'd20 → 7+zeka', 'orta'),
('zindan', 'Oda', 'Hazine Odası', 'Altın dolu bir oda! Ama ortadaki sandığa dikkat — muhtemelen tuzaklı.', 'd20 → 8+zeka', 'orta'),
('zindan', 'Oda', 'Hücre', 'Zindanda bir mahkûm hâlâ hayatta. Kurtarılmak istiyor ama güvenilir mi?', 'd20 → 6+karizma', 'kolay'),
('zindan', 'Oda', 'Simya Laboratuvarı', 'Terk edilmiş bir simya laboratuvarı. Masada yarım kalmış bir iksir var.', 'd20 → 7+zeka', 'orta'),
('zindan', 'Oda', 'İşkence Odası', 'Korkunç aletlerle dolu bir oda. Duvardaki zincirlerden taze kan damlıyor.', 'd20 → 6+savunma', 'kolay'),
('zindan', 'Oda', 'Kütüphane', 'Tozlu kitaplarla dolu devasa bir oda. Bazı kitaplar büyülü görünüyor.', 'd20 → 7+zeka', 'orta'),
('zindan', 'Oda', 'Silah Deposu', 'Paslı silahlar ve zırhlarla dolu bir oda. Bazıları hâlâ işe yarar.', 'd20 → 5+güç', 'kolay'),
('zindan', 'Oda', 'Taht Odası', 'Karanlık bir taht odası. Taht üzerinde kemikten bir taç duruyor.', 'd20 → 9+zeka', 'zor'),
('zindan', 'Oda', 'Su Basan Oda', 'Oda suyla doluyor! Çıkış suyu kapamaktan geçiyor.', 'd20 → 8+güç', 'orta'),
('zindan', 'Oda', 'Büyülü Ayna', 'Dev bir ayna geleceği gösteriyor diyor ama görüntüler karanlık.', 'd20 → 8+zeka', 'orta'),
('zindan', 'Oda', 'Mushaf Odası', 'Duvarlarda antik yazıtlar. Doğru olanı okursan gizli kapı açılır.', 'd20 → 9+zeka', 'zor'),
('zindan', 'Tuzak', 'Buz Tuzağı', 'Oda aniden donuyor. Her şey buzla kaplanıyor.', 'd20 → 7+savunma', 'orta'),
('zindan', 'Tuzak', 'Ateş Sütunu', 'Zeminden ateş sütunları fışkırıyor. Zamanlamayı tutturmak şart.', 'd20 → 8+güç', 'orta'),
('zindan', 'Tuzak', 'Sarkaç Bıçaklar', 'Tavandan sarkaç gibi sallanan dev bıçaklar. Aralarından geçmek lazım.', 'd20 → 8+güç', 'orta'),
('zindan', 'Tuzak', 'Lanet Sandık', 'Sandığı açanın eline lanet işleniyor.', 'd20 → 9+savunma', 'zor'),
('zindan', 'Tuzak', 'Teleport Kapanı', 'Yanlış kapıdan geçen başa dönüyor. Doğru yolu bulmak lazım.', 'd20 → 8+zeka', 'orta'),
('zindan', 'Canavar', 'Mimik Sandık', 'Masum görünen sandık aslında bir canavar! Açmaya çalışanı ısırıyor.', 'd20 → 7+atak', 'orta'),
('zindan', 'Canavar', 'Jelatinöz Küp', 'Koridoru kaplayan şeffaf bir jöle kütlesi. İçinden kemikler görünüyor.', 'd20 → 8+atak', 'orta'),
('zindan', 'Canavar', 'Gölge Avı', 'Meşaleniz sönüyor. Karanlıkta gölge yaratıklar saldırıyor.', 'd20 → 9+atak', 'zor'),
('zindan', 'Canavar', 'Dev Sıçanlar', 'Zindan sıçanları olağandışı büyük. Ve çok acıkmışlar.', 'd20 → 6+atak', 'kolay'),
('zindan', 'Canavar', 'Golem', 'Taştan yapılmış bir koruyucu canlanıyor. Emirlere uyuyor ama kimin emirleri?', 'd20 → 10+atak', 'zor'),
('zindan', 'Canavar', 'Yaratık Yumurtaları', 'Odanın köşesinde pulsuz yumurtalar. Bazıları çatlamak üzere.', 'd20 → 6+güç', 'kolay'),
('zindan', 'Bilmece', 'Heykel Bilmecesi', 'Dört heykel dört yöne bakıyor. Doğru yöne çevirmek kapıyı açar.', 'd20 → 7+zeka', 'orta'),
('zindan', 'Bilmece', 'Şifre Kapısı', 'Kapıda üç sembol var. Doğru sırayı bulmak lazım.', 'd20 → 8+zeka', 'orta'),
('zindan', 'Bilmece', 'Ağırlık Bulmacası', 'Ortadaki çanağa doğru ağırlığı koyarsanız kapı açılır.', 'd20 → 7+zeka', 'orta'),
('zindan', 'Bilmece', 'Konuşan Kapı', 'Kapı bir bilmece soruyor. Yanlış cevap verirseniz saldırıyor.', 'd20 → 9+zeka', 'zor'),
('zindan', 'Bilmece', 'Renk Bulmacası', 'Dört renkli taş ve dört yuva. Doğru taşı doğru yuvaya koyun.', 'd20 → 7+zeka', 'orta'),
('zindan', 'Boss', 'Liç Lordu', 'Zindanın derinliklerinde kadim bir liç bekliyor. Phylactery''sini bulmak lazım.', 'd20 → 12+atak', 'efsanevi'),
('zindan', 'Boss', 'Ejderha Kafası', 'Duvardan çıkan taş bir ejderha kafası alev saçıyor.', 'd20 → 10+savunma', 'zor'),
('zindan', 'Genel', 'Kayıp Maceracılar', 'Önceki bir grubun cesetleri. Günlükleri ipuçları içeriyor.', 'd20 → 5+zeka', 'kolay'),
('zindan', 'Genel', 'Büyülü Çeşme', 'İçen güç kazanıyor ama bedeli ne? Yazıtı oku.', 'd20 → 7+zeka', 'orta'),
('zindan', 'Genel', 'Çöken Tavan', 'Tavan çatırdıyor. Hızla geçmezseniz altında kalırsınız!', 'd20 → 7+güç', 'orta'),
('zindan', 'Genel', 'Kurukafa Avize', 'Tavandan asılı kafatası avize. İçinde bir anahtar parlıyor.', 'd20 → 6+güç', 'kolay'),
